#teste 1 C_beta == S_beta == beta
def teste1(Y, k): 
    n = len(Y)
    beta = (n * k) / np.sum(Y)

    logL0 = (
        (n * k * np.log(beta))
        - (n * gammaln(k))
        + ((k - 1) * np.sum(np.log(Y)))
        - (beta * np.sum(Y))
    )

    L0 = np.exp(logL0)

    print("Beta: ", beta)
    print("LogL0: ", logL0)
    print("L0: ", L0)

    return logL0

print("Teste 1:")
ll0 = teste1(Yt, kt)

#-----------------------------------------------------------------------------------------------------------------------

#teste 2 C_beta != S_beta
def teste2(Yc, Ys, k):
    nc = len(Yc)
    ns = len(Ys)
    C_beta = (nc * k) / np.sum(Yc)
    S_beta = (ns * k) / np.sum(Ys)

    logL1 = (
        nc * k * np.log(C_beta)
        - nc * gammaln(k)
        + (k - 1) * np.sum(np.log(Yc))
        - C_beta * np.sum(Yc)
        +
        ns * k * np.log(S_beta)
        - ns * gammaln(k)
        + (k - 1) * np.sum(np.log(Ys))
        - S_beta * np.sum(Ys)
    )

    L1 = np.exp(logL1)

    print("C_beta: ", C_beta)
    print("S_beta: ", S_beta)
    print("LogL1: ", logL1)
    print("L1: ", L1)

    return logL1

print("Teste 2:")
ll1 = teste2(Yc, Ys, kt)

